import { useCallback, useEffect, useRef, useState } from 'react';
import { clsx } from 'clsx';
import confetti from 'canvas-confetti';
import { BatteryFull, ChevronUp, Dumbbell, House, LineChart as LineIcon, Signal, User, Wifi } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import './index.css';
import type { Routine, Session } from './data/seed';
import { useFitness } from './lib/store';
import { doneSets, elapsedMs, totalSets, useLiveSession } from './lib/session';
import { clock } from './lib/stats';
import Home from './components/Home';
import Routines from './components/Routines';
import RoutineEditor from './components/RoutineEditor';
import SessionScreen from './components/Session';
import Progress from './components/Progress';
import Profile from './components/Profile';
import { TrendPanel, WeekPanel } from './components/SidePanels';
import { Btn, Sheet, Toast } from './components/ui';
import type { ToastMsg } from './components/ui';

type View = 'inicio' | 'rutinas' | 'progreso' | 'perfil';
const NAV: { id: View; label: string; icon: LucideIcon }[] = [
  { id: 'inicio', label: 'Inicio', icon: House },
  { id: 'rutinas', label: 'Rutinas', icon: Dumbbell },
  { id: 'progreso', label: 'Progreso', icon: LineIcon },
  { id: 'perfil', label: 'Perfil', icon: User },
];
const readHash = (): View => {
  const h = window.location.hash.replace('#/', '') as View;
  return NAV.some(n => n.id === h) ? h : 'inicio';
};

export default function App() {
  const fit = useFitness();
  const live = useLiveSession();
  const [view, setView] = useState<View>(readHash);
  const [sessionOpen, setSessionOpen] = useState(false);
  const [editing, setEditing] = useState<Routine | 'new' | null>(null);
  const [confirm, setConfirm] = useState<{ title: string; text: string; cta: string; run: () => void } | null>(null);
  const [toast, setToast] = useState<ToastMsg | null>(null);
  const scroller = useRef<HTMLElement>(null);
  const notify = (text: string, action?: ToastMsg['action']) => setToast({ id: Date.now(), text, action });
  const closeToast = useCallback(() => setToast(null), []);

  useEffect(() => {
    const on = () => setView(readHash());
    window.addEventListener('hashchange', on);
    return () => window.removeEventListener('hashchange', on);
  }, []);

  const go = (v: View) => {
    setView(v);
    setSessionOpen(false);
    try { window.history.replaceState(null, '', `#/${v}`); } catch { /* vista previa sin URL */ }
    scroller.current?.scrollTo({ top: 0 });
  };

  const start = (r: Routine) => {
    if (live.live) { setSessionOpen(true); notify('Ya tienes una sesión en curso.'); return; }
    live.start(r);
    setSessionOpen(true);
  };

  const saveSession = (s: Session, prs: string[]) => {
    fit.addSession(s);
    live.discard();
    setSessionOpen(false);
    go('progreso');
    notify(prs.length ? `Sesión guardada con ${prs.length} ${prs.length === 1 ? 'récord nuevo' : 'récords nuevos'}.` : 'Sesión guardada en tu historial.');
    try { confetti({ particleCount: 110, spread: 75, origin: { y: 0.7 }, colors: ['#FF5A2C', '#FFB627', '#5B7CFF', '#EFEDF7'] }); } catch { /* sin lienzo */ }
  };

  const { data } = fit;
  const l = live.live;

  return (
    <div className="pf-app pf-backdrop min-h-screen text-[#EFEDF7]">
      <div className="mx-auto flex max-w-[1240px] items-start justify-center lg:gap-12 lg:px-8 lg:pt-5">
        <aside className="hidden w-[300px] shrink-0 pt-8 xl:block" aria-label="Resumen de la semana"><WeekPanel data={data} /></aside>

        <div className="relative flex h-[100dvh] w-full max-w-[480px] flex-col overflow-hidden bg-[#12111C] lg:h-[760px] lg:w-[390px] lg:shrink-0 lg:rounded-[46px] lg:border-[9px] lg:border-[#25232F] lg:shadow-[0_40px_90px_-20px_rgba(0,0,0,.8)]">
          <div className="hidden h-8 shrink-0 items-center justify-between px-7 pt-1 text-[13px] font-semibold lg:flex" aria-hidden="true">
            <span className="pf-num">{new Date().toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })}</span>
            <span className="h-[22px] w-[92px] rounded-full bg-black" />
            <span className="flex items-center gap-1"><Signal size={14} /><Wifi size={14} /><BatteryFull size={18} /></span>
          </div>

          <main ref={scroller} className="pf-scroll flex-1 overflow-y-auto">
            {view === 'inicio' && <Home data={data} onStart={start} onSeeRoutines={() => go('rutinas')} onSeeProgress={() => go('progreso')} />}
            {view === 'rutinas' && (
              <Routines routines={data.routines} onStart={start} onEdit={setEditing}
                onDelete={r => setConfirm({ title: 'Borrar rutina', text: `Se borrará «${r.name}». Tu historial de sesiones se mantiene.`, cta: 'Borrar rutina', run: () => { fit.deleteRoutine(r.id); notify(`«${r.name}» borrada.`, { label: 'Deshacer', run: () => fit.saveRoutine(r) }); } })} />
            )}
            {view === 'progreso' && <Progress history={data.history} profile={data.profile} onDelete={s => { fit.deleteSession(s.id); notify('Sesión borrada del historial.', { label: 'Deshacer', run: () => fit.restoreSession(s) }); }} />}
            {view === 'perfil' && (
              <Profile key={JSON.stringify(data.profile)} profile={data.profile} history={data.history}
                onSave={p => { fit.updateProfile(p); notify('Objetivos y perfil actualizados.'); }}
                onReset={() => setConfirm({ title: 'Restablecer datos', text: 'Volverás a las rutinas, el historial y los objetivos de ejemplo. Perderás los cambios guardados.', cta: 'Restablecer', run: () => { fit.reset(); live.discard(); notify('Datos de ejemplo restablecidos.'); } })} />
            )}
          </main>

          {l && !sessionOpen && (
            <button onClick={() => setSessionOpen(true)} className="pf-pop mx-3 mb-2 flex items-center gap-3 rounded-2xl bg-[#FF5A2C] px-4 py-2.5 text-left text-[#0B0A12] shadow-lg hover:bg-[#FF7149]">
              <span className={clsx('h-2 w-2 rounded-full bg-[#0B0A12]', !l.paused && 'pf-live-dot')} />
              <span className="min-w-0 flex-1">
                <span className="block truncate text-[14px] font-bold">{l.name} · {l.paused ? 'en pausa' : l.rest ? 'descansando' : 'en curso'}</span>
                <span className="block text-[12px] font-medium opacity-80">{doneSets(l)} de {totalSets(l)} series</span>
              </span>
              <span className="pf-display pf-num text-[24px]">{clock(elapsedMs(l, live.now))}</span>
              <ChevronUp size={20} />
            </button>
          )}

          <nav aria-label="Navegación principal" className="grid shrink-0 grid-cols-4 border-t border-white/[0.07] bg-[#12111C] px-2 pt-2 pb-[46px] lg:pb-4">
            {NAV.map(n => {
              const on = view === n.id;
              return (
                <button key={n.id} onClick={() => go(n.id)} aria-current={on ? 'page' : undefined}
                  className={clsx('flex flex-col items-center gap-1 rounded-xl py-1.5 text-[11px] font-semibold transition', on ? 'text-[#FF6A3F]' : 'text-[#8C89A3] hover:text-[#EFEDF7]')}>
                  <span className={clsx('grid h-8 w-14 place-items-center rounded-full transition', on && 'bg-[#FF5A2C]/15')}><n.icon size={20} strokeWidth={on ? 2.4 : 2} /></span>
                  {n.label}
                </button>
              );
            })}
          </nav>

          {l && sessionOpen && <SessionScreen api={live} history={data.history} onMinimize={() => setSessionOpen(false)} onSave={saveSession} />}

          {editing && (
            <RoutineEditor routine={editing === 'new' ? null : editing} onClose={() => setEditing(null)}
              onSave={r => { fit.saveRoutine(r); setEditing(null); notify(editing === 'new' ? `Rutina «${r.name}» creada.` : 'Cambios guardados.'); }} />
          )}
          {confirm && (
            <Sheet title={confirm.title} onClose={() => setConfirm(null)}
              footer={<div className="flex gap-2"><Btn kind="soft" className="flex-1" onClick={() => setConfirm(null)}>Cancelar</Btn><Btn kind="danger" className="flex-1" onClick={() => { confirm.run(); setConfirm(null); }}>{confirm.cta}</Btn></div>}>
              <p className="text-[15px] leading-relaxed text-[#C9C6D8]">{confirm.text}</p>
            </Sheet>
          )}
          <Toast toast={toast} onClose={closeToast} />
        </div>

        <aside className="hidden w-[300px] shrink-0 pt-8 lg:block" aria-label="Tendencias de progreso"><TrendPanel data={data} /></aside>
      </div>
    </div>
  );
}

import { ChevronRight, Clock, Dumbbell, Flame, Play } from 'lucide-react';
import { clsx } from 'clsx';
import type { FitData } from '../lib/store';
import type { Routine } from '../data/seed';
import { IMG } from '../data/images';
import { dayIdx, kgShort, nextRoutine, relDate, ringPct, sameDay, sessionSets, sessionVolume, streakWeeks, weekSummary } from '../lib/stats';
import { Rings } from './charts';
import { C } from './ui';

const DAYS = ['L', 'M', 'X', 'J', 'V', 'S', 'D'];

export default function Home({ data, onStart, onSeeRoutines, onSeeProgress }: { data: FitData; onStart: (r: Routine) => void; onSeeRoutines: () => void; onSeeProgress: () => void }) {
  const { profile, history, routines } = data;
  const week = weekSummary(history);
  const streak = streakWeeks(history, profile.goalSessions);
  const next = nextRoutine(routines, history);
  const today = new Date();
  const first = profile.name.split(' ')[0];
  const rings = [
    { label: 'Sesiones', value: `${week.sessions}/${profile.goalSessions}`, pct: ringPct(week.sessions, profile.goalSessions), color: C.brasa },
    { label: 'Minutos', value: `${week.minutes}/${profile.goalMinutes}`, pct: ringPct(week.minutes, profile.goalMinutes), color: C.cobalto },
    { label: 'Volumen', value: kgShort(week.volume), pct: ringPct(week.volume, profile.goalVolume), color: C.ambar },
  ];

  return (
    <div className="px-5 pb-6">
      <header className="flex items-center justify-between pt-4">
        <div>
          <p className="text-[13px] text-[#A8A5BC] first-letter:uppercase">{today.toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' })}</p>
          <h1 className="pf-display mt-1 text-[34px]">Vamos, {first}</h1>
        </div>
        <div className="flex items-center gap-1.5 rounded-full bg-[#FF5A2C]/15 py-1.5 pl-2 pr-3 text-[#FF8A63]" title="Semanas seguidas cumpliendo tu objetivo">
          <Flame size={17} fill="currentColor" />
          <span className="pf-display pf-num text-[20px]">{streak}</span>
          <span className="text-[12px] font-semibold">sem.</span>
        </div>
      </header>

      <section aria-label="Objetivo semanal" className="mt-5 rounded-[26px] bg-[#17161F] p-4">
        <div className="flex items-center gap-4">
          <Rings size={128} stroke={13} gap={3} rings={rings} />
          <ul className="flex-1 space-y-2.5">
            {rings.map(r => (
              <li key={r.label}>
                <div className="flex items-center gap-2 text-[12px] text-[#A8A5BC]"><span className="h-2 w-2 rounded-full" style={{ background: r.color }} />{r.label}</div>
                <div className="pf-display pf-num text-[22px]" style={{ color: r.color }}>{r.value}</div>
              </li>
            ))}
          </ul>
        </div>
        <div className="mt-4 grid grid-cols-7 gap-1.5">
          {DAYS.map((d, i) => {
            const date = new Date(today); date.setDate(today.getDate() - dayIdx(today) + i);
            const trained = week.list.some(s => sameDay(new Date(s.date), date));
            const isToday = i === dayIdx(today);
            return (
              <div key={d} className="flex flex-col items-center gap-1.5">
                <span className={clsx('text-[11px]', isToday ? 'font-bold text-[#EFEDF7]' : 'text-[#8C89A3]')}>{d}</span>
                <span className={clsx('grid h-8 w-8 place-items-center rounded-full text-[12px] font-semibold',
                  trained ? 'bg-[#FF5A2C] text-[#0B0A12]' : isToday ? 'border-2 border-dashed border-[#FF5A2C]/70 text-[#EFEDF7]' : 'bg-white/[0.05] text-[#77748C]')}>
                  {trained ? <Dumbbell size={14} /> : date.getDate()}
                </span>
              </div>
            );
          })}
        </div>
      </section>

      {next && (
        <section className="mt-5" aria-label="Entrenamiento de hoy">
          <h2 className="mb-2.5 text-[15px] font-semibold">Hoy toca</h2>
          <div className="relative overflow-hidden rounded-[26px] bg-[#2A1A14]">
            <img src={IMG(next.photo)} alt={next.photo === 'gym-1' ? 'Barra olímpica con discos en el gimnasio' : 'Mujer haciendo abdominales en el gimnasio'} className="h-[190px] w-full object-cover" />
            <div className="absolute inset-0 bg-gradient-to-t from-[#0B0A12] via-[#0B0A12]/55 to-transparent" />
            <div className="absolute inset-x-0 bottom-0 p-4">
              <div className="flex items-end justify-between gap-3">
                <div className="min-w-0">
                  <p className="text-[12px] font-semibold text-[#FFB627]">{next.focus}</p>
                  <h3 className="pf-display mt-0.5 text-[32px] leading-none">{next.name}</h3>
                  <p className="mt-1.5 flex items-center gap-3 text-[13px] text-[#D7D4E4]">
                    <span className="flex items-center gap-1"><Clock size={13} />{next.minutes} min</span>
                    <span>{next.exercises.length} ejercicios</span>
                  </p>
                </div>
                <button onClick={() => onStart(next)} className="flex h-14 shrink-0 items-center gap-2 rounded-2xl bg-[#FF5A2C] px-5 text-[15px] font-bold text-[#0B0A12] hover:bg-[#FF7149] active:scale-[0.98]">
                  <Play size={17} fill="currentColor" /> Entrenar
                </button>
              </div>
            </div>
          </div>
        </section>
      )}

      <section className="mt-6" aria-label="Últimas sesiones">
        <div className="mb-1 flex items-center justify-between">
          <h2 className="text-[15px] font-semibold">Últimas sesiones</h2>
          <button onClick={onSeeProgress} className="flex items-center text-[13px] font-semibold text-[#FF8A63] hover:text-[#FFB08F]">Historial <ChevronRight size={16} /></button>
        </div>
        {history.length === 0 ? (
          <p className="py-6 text-center text-sm text-[#A8A5BC]">Aún no hay sesiones. Empieza una rutina y aparecerá aquí.</p>
        ) : (
          <ul className="divide-y divide-white/[0.07]">
            {history.slice(0, 3).map(s => (
              <li key={s.id} className="flex items-center gap-3 py-3">
                <span className="grid h-10 w-10 place-items-center rounded-xl bg-white/[0.06] text-[#FFB627]"><Dumbbell size={18} /></span>
                <div className="min-w-0 flex-1">
                  <p className="truncate text-[15px] font-semibold">{s.name}</p>
                  <p className="text-[12px] text-[#A8A5BC]">{relDate(s.date)} · {s.minutes} min</p>
                </div>
                <span className="pf-display pf-num text-[19px]">{sessionVolume(s) ? kgShort(sessionVolume(s)) : `${sessionSets(s)} series`}</span>
              </li>
            ))}
          </ul>
        )}
        <button onClick={onSeeRoutines} className="mt-2 flex w-full items-center justify-between rounded-2xl bg-white/[0.05] px-4 py-3.5 text-[14px] font-semibold hover:bg-white/[0.08]">
          Ver todas las rutinas <ChevronRight size={18} className="text-[#A8A5BC]" />
        </button>
      </section>
    </div>
  );
}

import { useState } from 'react';
import { RotateCcw } from 'lucide-react';
import type { Profile as P, Session } from '../data/seed';
import { IMG } from '../data/images';
import { kgShort, sessionVolume, streakWeeks } from '../lib/stats';
import { Btn, Field, inputCls } from './ui';

type Form = Record<keyof P, string>;
const toForm = (p: P): Form => ({ name: p.name, bodyWeight: String(p.bodyWeight).replace('.', ','), height: String(p.height), goalSessions: String(p.goalSessions), goalMinutes: String(p.goalMinutes), goalVolume: String(p.goalVolume) });
const n = (v: string) => Number(v.replace(',', '.'));

const RULES: { k: Exclude<keyof P, 'name'>; min: number; max: number; msg: string }[] = [
  { k: 'bodyWeight', min: 30, max: 250, msg: 'Peso entre 30 y 250 kg.' },
  { k: 'height', min: 120, max: 230, msg: 'Altura entre 120 y 230 cm.' },
  { k: 'goalSessions', min: 1, max: 7, msg: 'Entre 1 y 7 sesiones por semana.' },
  { k: 'goalMinutes', min: 30, max: 1200, msg: 'Entre 30 y 1.200 minutos.' },
  { k: 'goalVolume', min: 1000, max: 200000, msg: 'Entre 1.000 y 200.000 kg.' },
];

export default function Profile({ profile, history, onSave, onReset }: { profile: P; history: Session[]; onSave: (p: P) => void; onReset: () => void }) {
  const [f, setF] = useState<Form>(() => toForm(profile));
  const [err, setErr] = useState<Partial<Record<keyof P, string>>>({});
  const dirty = JSON.stringify(f) !== JSON.stringify(toForm(profile));
  const set = (k: keyof P) => (e: { target: { value: string } }) => setF(x => ({ ...x, [k]: k === 'name' ? e.target.value : e.target.value.replace(/[^\d.,]/g, '') }));

  const totalVol = history.reduce((a, s) => a + sessionVolume(s), 0);
  const totalMin = history.reduce((a, s) => a + s.minutes, 0);

  const save = () => {
    const e: Partial<Record<keyof P, string>> = {};
    if (f.name.trim().length < 2) e.name = 'Escribe tu nombre.';
    for (const r of RULES) { const v = n(f[r.k]); if (!Number.isFinite(v) || v < r.min || v > r.max) e[r.k] = r.msg; }
    setErr(e);
    if (Object.keys(e).length) return;
    onSave({ name: f.name.trim(), bodyWeight: n(f.bodyWeight), height: Math.round(n(f.height)), goalSessions: Math.round(n(f.goalSessions)), goalMinutes: Math.round(n(f.goalMinutes)), goalVolume: Math.round(n(f.goalVolume)) });
  };

  const goalSessions = Math.round(n(f.goalSessions)) || 0;

  return (
    <div className="px-5 pb-6">
      <header className="flex items-center gap-4 pt-5">
        <img src={IMG('persona-1')} alt={`Foto de ${profile.name}`} className="h-[72px] w-[72px] rounded-full bg-[#2A1A14] object-cover ring-2 ring-[#FF5A2C] ring-offset-2 ring-offset-[#12111C]" />
        <div className="min-w-0">
          <h1 className="pf-display truncate text-[32px]">{profile.name}</h1>
          <p className="text-[13px] text-[#A8A5BC]">{profile.bodyWeight.toLocaleString('es-ES')} kg · {profile.height} cm · socia desde marzo</p>
        </div>
      </header>

      <dl className="mt-5 grid grid-cols-3 divide-x divide-white/[0.08] rounded-[22px] bg-[#17161F] py-3 text-center">
        {[['Sesiones', String(history.length)], ['Horas', String(Math.round(totalMin / 60))], ['Levantado', kgShort(totalVol)]].map(([l, v]) => (
          <div key={l}><dd className="pf-display pf-num text-[24px]">{v}</dd><dt className="text-[12px] text-[#A8A5BC]">{l}</dt></div>
        ))}
      </dl>

      <section className="mt-6" aria-label="Objetivos semanales">
        <h2 className="text-[15px] font-semibold">Objetivos semanales</h2>
        <p className="mt-0.5 text-[12px] text-[#A8A5BC]">Mueven los anillos de inicio y la racha ({streakWeeks(history, profile.goalSessions)} semanas ahora).</p>
        <div className="mt-3">
          <span className="mb-1.5 block text-[13px] font-medium text-[#A8A5BC]">Sesiones por semana</span>
          <div className="grid grid-cols-7 gap-1.5" role="radiogroup" aria-label="Sesiones por semana">
            {[1, 2, 3, 4, 5, 6, 7].map(v => (
              <button key={v} role="radio" aria-checked={goalSessions === v} onClick={() => setF(x => ({ ...x, goalSessions: String(v) }))}
                className={'pf-display pf-num h-11 rounded-xl text-[20px] transition ' + (goalSessions === v ? 'bg-[#FF5A2C] text-[#0B0A12]' : 'bg-white/[0.06] hover:bg-white/10')}>{v}</button>
            ))}
          </div>
          {err.goalSessions && <p className="mt-1 text-[12px] text-[#FF8A8A]">{err.goalSessions}</p>}
        </div>
        <div className="mt-3 grid grid-cols-2 gap-3">
          <Field label="Minutos activos" error={err.goalMinutes}><input inputMode="numeric" className={inputCls(err.goalMinutes)} value={f.goalMinutes} onChange={set('goalMinutes')} /></Field>
          <Field label="Volumen (kg)" error={err.goalVolume}><input inputMode="numeric" className={inputCls(err.goalVolume)} value={f.goalVolume} onChange={set('goalVolume')} /></Field>
        </div>
      </section>

      <section className="mt-6" aria-label="Datos personales">
        <h2 className="text-[15px] font-semibold">Datos personales</h2>
        <div className="mt-3 space-y-3">
          <Field label="Nombre" error={err.name}><input className={inputCls(err.name)} value={f.name} onChange={set('name')} /></Field>
          <div className="grid grid-cols-2 gap-3">
            <Field label="Peso corporal (kg)" error={err.bodyWeight}><input inputMode="decimal" className={inputCls(err.bodyWeight)} value={f.bodyWeight} onChange={set('bodyWeight')} /></Field>
            <Field label="Altura (cm)" error={err.height}><input inputMode="numeric" className={inputCls(err.height)} value={f.height} onChange={set('height')} /></Field>
          </div>
        </div>
      </section>

      <div className="mt-5 flex gap-2">
        {dirty && <Btn kind="soft" onClick={() => { setF(toForm(profile)); setErr({}); }} className="flex-1">Descartar</Btn>}
        <Btn onClick={save} disabled={!dirty} className="flex-[2]">Guardar cambios</Btn>
      </div>

      <button onClick={onReset} className="mt-8 flex w-full items-center justify-center gap-2 rounded-2xl py-3 text-[13px] font-semibold text-[#A8A5BC] hover:bg-white/5 hover:text-[#EFEDF7]">
        <RotateCcw size={15} /> Restablecer datos de ejemplo
      </button>
    </div>
  );
}

import { useMemo, useState } from 'react';
import { clsx } from 'clsx';
import { Trash2, Trophy } from 'lucide-react';
import type { Profile, Session } from '../data/seed';
import { exerciseSeries, kg, kgShort, personalRecords, relDate, sessionSets, sessionVolume, weeklySeries } from '../lib/stats';
import { BarChart, LineChart } from './charts';
import { C } from './ui';

type Metric = 'volume' | 'minutes' | 'sessions';
const METRICS: { id: Metric; label: string; color: string }[] = [
  { id: 'volume', label: 'Volumen', color: C.ambar },
  { id: 'minutes', label: 'Minutos', color: C.cobalto },
  { id: 'sessions', label: 'Sesiones', color: C.brasa },
];
const LIFTS = ['Press banca', 'Sentadilla', 'Peso muerto rumano', 'Remo con barra'];

export default function Progress({ history, profile, onDelete }: { history: Session[]; profile: Profile; onDelete: (s: Session) => void }) {
  const [metric, setMetric] = useState<Metric>('volume');
  const [lift, setLift] = useState(LIFTS[0]);
  const [showAll, setShowAll] = useState(false);
  const weeks = useMemo(() => weeklySeries(history, 8), [history]);
  const m = METRICS.find(x => x.id === metric)!;
  const goal = metric === 'volume' ? profile.goalVolume : metric === 'minutes' ? profile.goalMinutes : profile.goalSessions;
  const fmt = (n: number) => (metric === 'volume' ? kgShort(n) : metric === 'minutes' ? `${n} min` : `${n} sesiones`);
  const series = exerciseSeries(history, lift).slice(-12);
  const prs = personalRecords(history);
  const pr = prs.find(p => p.name === lift);
  const first = series[0]?.weight ?? 0, lastW = series[series.length - 1]?.weight ?? 0;
  const shown = showAll ? history : history.slice(0, 6);

  return (
    <div className="px-5 pb-6">
      <header className="pt-4">
        <h1 className="pf-display text-[34px]">Progreso</h1>
        <p className="mt-1 text-[13px] text-[#A8A5BC]">{history.length} sesiones registradas · últimas 8 semanas</p>
      </header>

      <section className="mt-4 rounded-[26px] bg-[#17161F] p-4" aria-label="Resumen semanal">
        <div className="flex gap-1 rounded-xl bg-white/[0.05] p-1" role="tablist">
          {METRICS.map(x => (
            <button key={x.id} role="tab" aria-selected={metric === x.id} onClick={() => setMetric(x.id)}
              className={clsx('h-8 flex-1 rounded-lg text-[13px] font-semibold transition', metric === x.id ? 'bg-[#EFEDF7] text-[#0B0A12]' : 'text-[#A8A5BC] hover:text-[#EFEDF7]')}>{x.label}</button>
          ))}
        </div>
        <div className="mt-3 flex items-baseline justify-between">
          <p className="pf-display pf-num text-[30px]" style={{ color: m.color }}>{fmt(weeks[weeks.length - 1][metric])}</p>
          <p className="text-[12px] text-[#A8A5BC]">esta semana · objetivo {fmt(goal)}</p>
        </div>
        <div className="mt-2"><BarChart key={metric} data={weeks.map(w => ({ label: w.label, value: w[metric] }))} goal={goal} color={m.color} format={fmt} /></div>
      </section>

      <section className="mt-4 rounded-[26px] bg-[#17161F] p-4" aria-label="Evolución por ejercicio">
        <div className="flex items-start justify-between gap-2">
          <div>
            <h2 className="text-[15px] font-semibold">Peso máximo</h2>
            <p className="text-[12px] text-[#A8A5BC]">{series.length ? `${lastW - first >= 0 ? '+' : ''}${kg(lastW - first)} kg en ${series.length} sesiones` : 'Sin registros todavía'}</p>
          </div>
          {pr && <span className="flex items-center gap-1 rounded-full bg-[#FFB627]/[0.14] px-2.5 py-1 text-[12px] font-semibold text-[#FFC85A]"><Trophy size={13} />Récord {kg(pr.weight)} kg</span>}
        </div>
        <div className="pf-scroll -mx-4 mt-3 flex gap-1.5 overflow-x-auto px-4">
          {LIFTS.map(l => (
            <button key={l} onClick={() => setLift(l)} aria-pressed={lift === l}
              className={clsx('h-8 shrink-0 rounded-full px-3 text-[12px] font-semibold transition', lift === l ? 'bg-[#FFB627] text-[#0B0A12]' : 'bg-white/[0.06] text-[#C9C6D8] hover:bg-white/10')}>{l}</button>
          ))}
        </div>
        <div className="mt-4"><LineChart key={lift} data={series.map(s => ({ label: new Date(s.date).toLocaleDateString('es-ES', { day: 'numeric', month: 'short' }).replace('.', ''), value: s.weight }))} format={n => `${kg(n)} kg`} /></div>
      </section>

      <section className="mt-6" aria-label="Historial">
        <h2 className="mb-1 text-[15px] font-semibold">Historial</h2>
        {history.length === 0 ? (
          <p className="py-6 text-center text-sm text-[#A8A5BC]">Sin sesiones. Cuando guardes una, verás aquí su duración y volumen.</p>
        ) : (
          <ul className="divide-y divide-white/[0.07]">
            {shown.map(s => (
              <li key={s.id} className="group flex items-center gap-3 py-3">
                <div className="w-12 shrink-0 text-center">
                  <p className="pf-display pf-num text-[24px] leading-none">{new Date(s.date).getDate()}</p>
                  <p className="text-[11px] text-[#8C89A3]">{new Date(s.date).toLocaleDateString('es-ES', { month: 'short' }).replace('.', '')}</p>
                </div>
                <div className="min-w-0 flex-1">
                  <p className="truncate text-[15px] font-semibold">{s.name}</p>
                  <p className="text-[12px] text-[#A8A5BC]">{relDate(s.date)} · {s.minutes} min · {sessionSets(s)} series</p>
                </div>
                <span className="pf-num text-[14px] font-semibold">{sessionVolume(s) ? kgShort(sessionVolume(s)) : 'Corporal'}</span>
                <button onClick={() => onDelete(s)} aria-label={`Borrar sesión ${s.name} del ${new Date(s.date).toLocaleDateString('es-ES')}`} className="grid h-9 w-9 place-items-center rounded-xl text-[#8C89A3] hover:bg-white/10 hover:text-[#FF8A8A]"><Trash2 size={15} /></button>
              </li>
            ))}
          </ul>
        )}
        {history.length > 6 && (
          <button onClick={() => setShowAll(v => !v)} className="mt-2 h-11 w-full rounded-2xl bg-white/[0.05] text-[14px] font-semibold hover:bg-white/[0.08]">
            {showAll ? 'Mostrar menos' : `Ver las ${history.length} sesiones`}
          </button>
        )}
      </section>
    </div>
  );
}

import { useState } from 'react';
import { Plus, Trash2 } from 'lucide-react';
import type { Exercise, Focus, Routine } from '../data/seed';
import { FOCUSES } from '../data/seed';
import { uid } from '../lib/store';
import { Btn, Field, Sheet, inputCls } from './ui';

type Draft = { name: string; sets: string; reps: string; weight: string; rest: string; unit?: Exercise['unit'] };
const blankEx = (): Draft => ({ name: '', sets: '3', reps: '10', weight: '20', rest: '90' });
const toDraft = (e: Exercise): Draft => ({ name: e.name, sets: String(e.sets), reps: String(e.reps), weight: String(e.weight).replace('.', ','), rest: String(e.rest), unit: e.unit });
const num = (v: string) => Number(v.replace(',', '.'));

export default function RoutineEditor({ routine, onSave, onClose }: { routine: Routine | null; onSave: (r: Routine) => void; onClose: () => void }) {
  const [name, setName] = useState(routine?.name ?? '');
  const [subtitle, setSubtitle] = useState(routine?.subtitle ?? '');
  const [focus, setFocus] = useState<Focus>(routine?.focus ?? 'Hipertrofia');
  const [minutes, setMinutes] = useState(String(routine?.minutes ?? 45));
  const [exs, setExs] = useState<Draft[]>(routine ? routine.exercises.map(toDraft) : [blankEx()]);
  const [errors, setErrors] = useState<Record<string, string>>({});

  const setEx = (i: number, k: keyof Draft, v: string) =>
    setExs(list => list.map((e, j) => (j !== i ? e : { ...e, [k]: k === 'name' ? v : v.replace(/[^\d.,]/g, '') })));

  const submit = () => {
    const err: Record<string, string> = {};
    if (name.trim().length < 2) err.name = 'Ponle un nombre de al menos 2 letras.';
    const m = Number(minutes);
    if (!Number.isFinite(m) || m < 5 || m > 180) err.minutes = 'Entre 5 y 180 minutos.';
    if (!exs.length) err.exs = 'Añade al menos un ejercicio.';
    exs.forEach((e, i) => {
      if (!e.name.trim()) err[`ex${i}`] = 'Escribe el nombre del ejercicio.';
      else if (!(num(e.sets) >= 1 && num(e.sets) <= 10) || !(num(e.reps) >= 1)) err[`ex${i}`] = 'Revisa series (1-10) y repeticiones.';
      else if (!(num(e.weight) >= 0) || !(num(e.rest) >= 0)) err[`ex${i}`] = 'El peso y el descanso deben ser números.';
    });
    setErrors(err);
    if (Object.keys(err).length) return;
    onSave({
      id: routine?.id ?? uid(), name: name.trim(), subtitle: subtitle.trim() || `${exs.length} ejercicios`, focus, minutes: m,
      photo: routine?.photo ?? (focus === 'Core' || focus === 'Full body' ? 'gym-2' : 'gym-1'),
      exercises: exs.map(e => ({ name: e.name.trim(), sets: Math.round(num(e.sets)), reps: Math.round(num(e.reps)), weight: num(e.weight) || 0, rest: Math.round(num(e.rest)) || 0, ...(e.unit ? { unit: e.unit } : {}) })),
    });
  };

  return (
    <Sheet title={routine ? 'Editar rutina' : 'Nueva rutina'} onClose={onClose}
      footer={<div className="flex gap-2"><Btn kind="soft" onClick={onClose} className="flex-1">Cancelar</Btn><Btn onClick={submit} className="flex-[2]">{routine ? 'Guardar cambios' : 'Crear rutina'}</Btn></div>}>
      <div className="space-y-4">
        <Field label="Nombre" error={errors.name}>
          <input className={inputCls(errors.name)} value={name} onChange={e => setName(e.target.value)} placeholder="Ej.: Torso fuerza" />
        </Field>
        <Field label="Descripción corta">
          <input className={inputCls()} value={subtitle} onChange={e => setSubtitle(e.target.value)} placeholder="Ej.: Pecho, espalda y hombro" />
        </Field>
        <div className="flex gap-3">
          <Field label="Enfoque">
            <select className={inputCls()} value={focus} onChange={e => setFocus(e.target.value as Focus)}>
              {FOCUSES.map(f => <option key={f} value={f} className="bg-[#1E1C28]">{f}</option>)}
            </select>
          </Field>
          <Field label="Duración (min)" error={errors.minutes}>
            <input className={inputCls(errors.minutes)} inputMode="numeric" value={minutes} onChange={e => setMinutes(e.target.value.replace(/\D/g, ''))} />
          </Field>
        </div>

        <div>
          <div className="mb-2 flex items-center justify-between">
            <h3 className="text-[15px] font-semibold">Ejercicios</h3>
            <span className="text-[12px] text-[#8C89A3]">series · reps · kg · descanso (s)</span>
          </div>
          {errors.exs && <p className="mb-2 text-[12px] text-[#FF8A8A]">{errors.exs}</p>}
          <ul className="space-y-2.5">
            {exs.map((e, i) => (
              <li key={i} className="rounded-2xl bg-white/[0.05] p-3">
                <div className="flex gap-2">
                  <input aria-label={`Nombre del ejercicio ${i + 1}`} className={inputCls(errors[`ex${i}`])} value={e.name} onChange={ev => setEx(i, 'name', ev.target.value)} placeholder="Ej.: Press banca" />
                  <button onClick={() => setExs(l => l.filter((_, j) => j !== i))} aria-label={`Quitar ejercicio ${i + 1}`} className="grid h-11 w-11 shrink-0 place-items-center rounded-xl text-[#FF8A8A] hover:bg-white/10"><Trash2 size={16} /></button>
                </div>
                <div className="mt-2 grid grid-cols-4 gap-2">
                  {(['sets', 'reps', 'weight', 'rest'] as const).map(k => (
                    <input key={k} aria-label={{ sets: 'Series', reps: 'Repeticiones', weight: 'Peso en kg', rest: 'Descanso en segundos' }[k]} inputMode="decimal"
                      className={inputCls() + ' text-center pf-num'} value={e[k]} onChange={ev => setEx(i, k, ev.target.value)} />
                  ))}
                </div>
                {errors[`ex${i}`] && <p className="mt-1.5 text-[12px] text-[#FF8A8A]">{errors[`ex${i}`]}</p>}
              </li>
            ))}
          </ul>
          <button onClick={() => setExs(l => [...l, blankEx()])} className="mt-3 flex h-11 w-full items-center justify-center gap-2 rounded-xl border border-dashed border-white/20 text-[14px] font-semibold text-[#C9C6D8] hover:bg-white/5">
            <Plus size={16} /> Añadir ejercicio
          </button>
        </div>
      </div>
    </Sheet>
  );
}

import { useMemo, useState } from 'react';
import { clsx } from 'clsx';
import { ChevronDown, Clock, Pencil, Play, Plus, Search, Trash2 } from 'lucide-react';
import type { Routine } from '../data/seed';
import { FOCUSES } from '../data/seed';
import { IMG } from '../data/images';

type Props = { routines: Routine[]; onStart: (r: Routine) => void; onEdit: (r: Routine | 'new') => void;  onDelete: (r: Routine) => void };

const fmtRest = (s: number) => (s >= 60 ? `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')} min` : `${s} s`);

export default function Routines({ routines, onStart, onEdit, onDelete }: Props) {
  const [q, setQ] = useState('');
  const [focus, setFocus] = useState<string>('Todas');
  const [open, setOpen] = useState<string | null>(null);

  const list = useMemo(() => {
    const n = q.trim().toLowerCase();
    return routines.filter(r =>
      (focus === 'Todas' || r.focus === focus) &&
      (!n || r.name.toLowerCase().includes(n) || r.subtitle.toLowerCase().includes(n) || r.exercises.some(e => e.name.toLowerCase().includes(n))));
  }, [routines, q, focus]);

  return (
    <div className="px-5 pb-6">
      <header className="flex items-end justify-between pt-4">
        <div>
          <h1 className="pf-display text-[34px]">Rutinas</h1>
          <p className="mt-1 text-[13px] text-[#A8A5BC]">{routines.length} planes guardados</p>
        </div>
        <button onClick={() => onEdit('new')} className="flex h-10 items-center gap-1.5 rounded-full bg-white/10 px-4 text-[14px] font-semibold hover:bg-white/15">
          <Plus size={16} /> Nueva
        </button>
      </header>

      <div className="relative mt-4">
        <Search size={17} className="pointer-events-none absolute left-3.5 top-1/2 -translate-y-1/2 text-[#8C89A3]" />
        <input value={q} onChange={e => setQ(e.target.value)} placeholder="Buscar rutina o ejercicio" aria-label="Buscar rutina o ejercicio"
          className="h-11 w-full rounded-xl border border-transparent bg-white/[0.07] pl-10 pr-3 text-[15px] text-[#EFEDF7] placeholder:text-[#77748C] outline-none focus:border-[#FFB627]" />
      </div>
      <div className="pf-scroll -mx-5 mt-3 flex gap-2 overflow-x-auto px-5" role="tablist" aria-label="Filtrar por enfoque">
        {['Todas', ...FOCUSES].map(f => (
          <button key={f} role="tab" aria-selected={focus === f} onClick={() => setFocus(f)}
            className={clsx('h-9 shrink-0 rounded-full px-4 text-[13px] font-semibold transition',
              focus === f ? 'bg-[#EFEDF7] text-[#0B0A12]' : 'bg-white/[0.06] text-[#C9C6D8] hover:bg-white/10')}>
            {f}
          </button>
        ))}
      </div>

      {list.length === 0 ? (
        <div className="mt-10 text-center">
          <p className="text-[15px] font-semibold">Ninguna rutina coincide</p>
          <p className="mt-1 text-[13px] text-[#A8A5BC]">Prueba con otro filtro o crea una rutina nueva.</p>
          <button onClick={() => { setQ(''); setFocus('Todas'); }} className="mt-4 rounded-full bg-white/10 px-4 py-2 text-[13px] font-semibold hover:bg-white/15">Quitar filtros</button>
        </div>
      ) : (
        <ul className="mt-4 space-y-3">
          {list.map(r => {
            const isOpen = open === r.id;
            return (
              <li key={r.id} className="overflow-hidden rounded-[22px] bg-[#17161F]">
                <div className="flex gap-3 p-3">
                  <img src={IMG(r.photo)} alt={r.photo === 'gym-1' ? 'Barra con discos' : 'Mujer entrenando abdominales'} loading="lazy" className="h-[84px] w-[76px] shrink-0 rounded-2xl bg-[#2A1A14] object-cover" />
                  <div className="min-w-0 flex-1">
                    <div className="flex items-start justify-between gap-2">
                      <div className="min-w-0">
                        <h2 className="pf-display truncate text-[24px] leading-none">{r.name}</h2>
                        <p className="mt-1 truncate text-[13px] text-[#A8A5BC]">{r.subtitle}</p>
                      </div>
                      <span className="shrink-0 rounded-full bg-[#FFB627]/15 px-2 py-0.5 text-[11px] font-semibold text-[#FFC85A]">{r.focus}</span>
                    </div>
                    <div className="mt-2 flex items-center gap-3 text-[12px] text-[#C9C6D8]">
                      <span className="flex items-center gap-1"><Clock size={13} />{r.minutes} min</span>
                      <span>{r.exercises.length} ejercicios</span>
                      <span>{r.exercises.reduce((a, e) => a + e.sets, 0)} series</span>
                    </div>
                  </div>
                </div>
                {isOpen && (
                  <ul className="pf-fade mx-3 mb-1 divide-y divide-white/[0.06] rounded-2xl bg-white/[0.04] px-3">
                    {r.exercises.map(e => (
                      <li key={e.name} className="flex items-center justify-between gap-2 py-2 text-[13px]">
                        <span className="min-w-0 truncate">{e.name}</span>
                        <span className="pf-num shrink-0 text-[#A8A5BC]">{e.sets}×{e.reps}{e.unit === 's' ? ' s' : ''} · {e.weight ? `${e.weight.toLocaleString('es-ES')} kg` : 'corporal'} · {fmtRest(e.rest)}</span>
                      </li>
                    ))}
                  </ul>
                )}
                <div className="flex items-center gap-1 p-3 pt-2">
                  <button onClick={() => onStart(r)}
                    className="flex h-10 flex-1 items-center justify-center gap-2 rounded-xl bg-[#FF5A2C] text-[14px] font-bold text-[#0B0A12] hover:bg-[#FF7149]">
                    <Play size={15} fill="currentColor" /> Empezar sesión
                  </button>
                  <button onClick={() => setOpen(isOpen ? null : r.id)} aria-expanded={isOpen} aria-label={isOpen ? 'Ocultar ejercicios' : 'Ver ejercicios'} className="grid h-10 w-10 place-items-center rounded-xl hover:bg-white/10">
                    <ChevronDown size={18} className={clsx('transition', isOpen && 'rotate-180')} />
                  </button>
                  <button onClick={() => onEdit(r)} aria-label={`Editar ${r.name}`} className="grid h-10 w-10 place-items-center rounded-xl hover:bg-white/10"><Pencil size={16} /></button>
                  <button onClick={() => onDelete(r)} aria-label={`Borrar ${r.name}`} className="grid h-10 w-10 place-items-center rounded-xl text-[#FF8A8A] hover:bg-white/10"><Trash2 size={16} /></button>
                </div>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

import { clsx } from 'clsx';
import { Check, ChevronDown, Pause, Play, SkipForward, Timer, Trophy } from 'lucide-react';
import type { Session as Logged } from '../data/seed';
import type { LiveApi } from '../lib/session';
import { doneSets, elapsedMs, liveVolume, restLeftMs, toSession, totalSets } from '../lib/session';
import { clock, kg, kgShort } from '../lib/stats';
import { Btn, Sheet, Stepper } from './ui';

type Props = { api: LiveApi; history: Logged[]; onMinimize: () => void; onSave: (s: Logged, prs: string[]) => void };

export default function SessionScreen({ api, history, onMinimize, onSave }: Props) {
  const { live, now } = api;
  if (!live) return null;
  const ex = live.exercises[live.cur.ex];
  const set = ex.sets[live.cur.set];
  const total = totalSets(live), done = doneSets(live);
  const restLeft = live.rest ? restLeftMs(live.rest, live.paused, now) : 0;
  const best = (name: string) => Math.max(0, ...history.flatMap(s => s.exercises.filter(e => e.name === name).map(e => e.weight)));
  const last = history.find(s => s.exercises.some(e => e.name === ex.name))?.exercises.find(e => e.name === ex.name);

  const R = 86, LEN = 2 * Math.PI * R;
  const restPct = live.rest ? restLeft / live.rest.total : 0;
  const next = live.exercises[live.cur.ex];

  const prs = live.exercises.filter(e => { const m = Math.max(0, ...e.sets.filter(s => s.done).map(s => s.weight)); return m > 0 && m > best(e.name); }).map(e => e.name);

  return (
    <div className="absolute inset-0 z-30 flex flex-col bg-[#0F0E17] pf-fade">
      <div className="h-0 lg:h-8 shrink-0" />
      <header className="flex items-center justify-between gap-2 px-3 py-2">
        <button onClick={onMinimize} aria-label="Minimizar sesión" className="grid h-10 w-10 place-items-center rounded-full hover:bg-white/10"><ChevronDown size={22} /></button>
        <div className="min-w-0 text-center">
          <p className="truncate text-[15px] font-semibold">{live.name}</p>
          <p className={clsx('flex items-center justify-center gap-1.5 text-[12px]', live.paused ? 'text-[#FFB627]' : 'text-[#FF8A63]')}>
            <span className={clsx('h-1.5 w-1.5 rounded-full bg-current', !live.paused && 'pf-live-dot')} />{live.paused ? 'En pausa' : 'En curso'}
          </p>
        </div>
        <button onClick={api.requestFinish} className="h-10 rounded-full px-3 text-[14px] font-semibold text-[#FF8A63] hover:bg-white/10">Terminar</button>
      </header>

      <div className="flex items-end justify-between px-5 pb-3">
        <div>
          <p className="text-[12px] text-[#A8A5BC]">Tiempo total</p>
          <p className="pf-display pf-num text-[52px] leading-none" aria-live="off">{clock(elapsedMs(live, now))}</p>
        </div>
        <div className="text-right">
          <p className="pf-display pf-num text-[22px]">{done}/{total} <span className="pf-app text-[12px] font-medium text-[#A8A5BC]">series</span></p>
          <p className="text-[12px] text-[#A8A5BC]">{kgShort(liveVolume(live))} levantados</p>
        </div>
      </div>
      <div className="mx-5 h-1.5 overflow-hidden rounded-full bg-white/10">
        <div className="h-full rounded-full bg-[#FF5A2C] transition-all duration-500" style={{ width: `${(done / total) * 100}%` }} />
      </div>

      <div className="pf-scroll flex-1 overflow-y-auto px-5 pt-4 pb-4">
        {live.rest ? (
          <section aria-label="Descanso" className="flex flex-col items-center rounded-[26px] bg-[#151A33] px-4 py-5">
            <div className="relative h-[196px] w-[196px]">
              <svg viewBox="0 0 196 196" className="h-full w-full -rotate-90">
                <circle cx={98} cy={98} r={R} fill="none" stroke="#5B7CFF" strokeOpacity={0.18} strokeWidth={12} />
                <circle cx={98} cy={98} r={R} fill="none" stroke="#5B7CFF" strokeWidth={12} strokeLinecap="round" strokeDasharray={LEN} strokeDashoffset={LEN * (1 - restPct)} style={{ transition: 'stroke-dashoffset .25s linear' }} />
              </svg>
              <div className="absolute inset-0 grid place-items-center text-center">
                <div>
                  <p className="text-[13px] text-[#B9C4FF]">Descanso</p>
                  <p className="pf-display pf-num text-[58px] leading-none" role="timer">{clock(restLeft + 999)}</p>
                </div>
              </div>
            </div>
            <div className="mt-3 flex gap-2">
              <button onClick={() => api.addRest(-15)} disabled={restLeft < 16000} className="h-9 rounded-full bg-white/10 px-4 text-[13px] font-semibold hover:bg-white/15 disabled:opacity-40">−15 s</button>
              <button onClick={() => api.addRest(15)} className="h-9 rounded-full bg-white/10 px-4 text-[13px] font-semibold hover:bg-white/15">+15 s</button>
            </div>
            <p className="mt-4 text-center text-[13px] text-[#C9C6D8]">Siguiente: <b className="text-[#EFEDF7]">{next.name}</b> · serie {live.cur.set + 1} de {next.sets.length} · {set.weight ? `${kg(set.weight)} kg` : 'peso corporal'}</p>
          </section>
        ) : (
          <section aria-label="Serie actual" className="rounded-[26px] bg-[#17161F] p-4">
            <p className="text-[12px] text-[#A8A5BC]">Ejercicio {live.cur.ex + 1} de {live.exercises.length}</p>
            <h2 className="pf-display mt-1 text-[30px] leading-[1]">{ex.name}</h2>
            <div className="mt-2 flex items-center justify-between text-[13px]">
              <span className="font-semibold text-[#FF8A63]">Serie {live.cur.set + 1} de {ex.sets.length}</span>
              {last && <span className="text-[#A8A5BC]">Última vez: {last.weight ? `${kg(last.weight)} kg × ${last.reps}` : `${last.reps}${ex.unit === 's' ? ' s' : ' reps'}`}</span>}
            </div>
            <div className="mt-3 flex gap-2">
              <Stepper label="Peso" unit="kg" step={2.5} value={set.weight} onChange={d => api.adjust('weight', d)} />
              <Stepper label={ex.unit === 's' ? 'Tiempo' : 'Repeticiones'} unit={ex.unit === 's' ? 's' : 'reps'} step={ex.unit === 's' ? 5 : 1} value={set.reps} onChange={d => api.adjust('reps', d)} />
            </div>
            <p className="mt-3 flex items-center gap-1.5 text-[12px] text-[#A8A5BC]"><Timer size={13} />Descanso tras la serie: {ex.rest} s</p>
          </section>
        )}

        <h3 className="mt-5 mb-2 text-[14px] font-semibold">Plan de hoy</h3>
        <ul className="space-y-1">
          {live.exercises.map((e, ei) => (
            <li key={ei} className={clsx('rounded-2xl px-3 py-2.5', ei === live.cur.ex ? 'bg-white/[0.06]' : '')}>
              <div className="flex items-center justify-between gap-2">
                <span className={clsx('truncate text-[14px]', e.sets.every(s => s.done) ? 'text-[#8C89A3] line-through' : 'font-medium')}>{e.name}</span>
                <span className="pf-num shrink-0 text-[12px] text-[#8C89A3]">{e.sets.filter(s => s.done).length}/{e.sets.length}</span>
              </div>
              <div className="mt-2 flex flex-wrap gap-1.5">
                {e.sets.map((s, si) => {
                  const current = ei === live.cur.ex && si === live.cur.set;
                  return (
                    <button key={si} onClick={() => (s.done ? api.undoSet(ei, si) : api.select(ei, si))}
                      aria-label={`${e.name}, serie ${si + 1}${s.done ? ', completada (pulsa para deshacer)' : ''}`}
                      className={clsx('flex h-8 min-w-[54px] items-center justify-center gap-1 rounded-full px-2.5 text-[12px] font-semibold pf-num transition',
                        s.done ? 'bg-[#FF5A2C] text-[#0B0A12]' : current ? 'border-2 border-[#FF5A2C] text-[#EFEDF7]' : 'bg-white/[0.06] text-[#A8A5BC] hover:bg-white/10')}>
                      {s.done && <Check size={12} strokeWidth={3} />}
                      {s.weight ? `${kg(s.weight)}×${s.reps}` : `${s.reps}${e.unit === 's' ? ' s' : ''}`}
                    </button>
                  );
                })}
              </div>
            </li>
          ))}
        </ul>
      </div>

      <footer className="flex gap-2 border-t border-white/[0.07] bg-[#0F0E17] px-4 pt-3 pb-[46px] lg:pb-5">
        <button onClick={api.togglePause} aria-label={live.paused ? 'Reanudar' : 'Pausar'}
          className="flex h-14 items-center gap-2 rounded-2xl bg-white/10 px-4 text-[14px] font-semibold hover:bg-white/15">
          {live.paused ? <Play size={18} fill="currentColor" /> : <Pause size={18} fill="currentColor" />}{live.paused ? 'Reanudar' : 'Pausar'}
        </button>
        {live.rest ? (
          <button onClick={api.skipRest} className="flex h-14 flex-1 items-center justify-center gap-2 rounded-2xl bg-[#5B7CFF] text-[16px] font-bold text-[#0B0A12] hover:bg-[#7690FF]">
            <SkipForward size={18} fill="currentColor" /> Saltar descanso
          </button>
        ) : (
          <button onClick={api.completeSet} disabled={live.paused} className="flex h-14 flex-1 items-center justify-center gap-2 rounded-2xl bg-[#FF5A2C] text-[16px] font-bold text-[#0B0A12] hover:bg-[#FF7149] disabled:opacity-40">
            <Check size={19} strokeWidth={3} /> Completar serie
          </button>
        )}
      </footer>

      {live.finished && (
        <Sheet title={done === total ? '¡Sesión completada!' : '¿Terminar la sesión?'} onClose={api.keepGoing}
          footer={
            <div className="flex gap-2">
              {done < total && <Btn kind="soft" onClick={api.keepGoing} className="flex-1">Seguir</Btn>}
              <Btn kind="danger" onClick={api.discard} className="flex-1">Descartar</Btn>
              <Btn onClick={() => onSave(toSession(live, now), prs)} disabled={done === 0} className="flex-[1.4]">{done < total ? 'Guardar' : 'Guardar sesión'}</Btn>
            </div>
          }>
          <div className="grid grid-cols-3 gap-2">
            {[['Duración', clock(elapsedMs(live, now))], ['Series', `${done}/${total}`], ['Volumen', kgShort(liveVolume(live))]].map(([l, v]) => (
              <div key={l} className="rounded-2xl bg-white/[0.06] p-3">
                <p className="text-[12px] text-[#A8A5BC]">{l}</p>
                <p className="pf-display pf-num mt-1 text-[24px]">{v}</p>
              </div>
            ))}
          </div>
          {done === 0 && <p className="mt-3 text-[13px] text-[#FFB627]">Aún no has completado ninguna serie: no hay nada que guardar.</p>}
          {prs.length > 0 && (
            <div className="mt-3 rounded-2xl bg-[#FFB627]/[0.12] p-3">
              <p className="flex items-center gap-2 text-[14px] font-semibold text-[#FFC85A]"><Trophy size={16} /> Nuevos récords</p>
              <p className="mt-1 text-[13px] text-[#E6E3F0]">{prs.join(', ')}</p>
            </div>
          )}
          {done < total && done > 0 && <p className="mt-3 text-[13px] text-[#A8A5BC]">Te quedan {total - done} series. Se guardarán solo las completadas.</p>}
        </Sheet>
      )}
    </div>
  );
}

import { Activity, Trophy } from 'lucide-react';
import type { FitData } from '../lib/store';
import { kg, kgShort, mondayOf, personalRecords, relDate, ringPct, sameDay, streakWeeks, weekSummary, weeklySeries } from '../lib/stats';
import { BarChart } from './charts';
import { C } from './ui';

const DAY = 86_400_000;

export function WeekPanel({ data }: { data: FitData }) {
  const { profile, history } = data;
  const w = weekSummary(history);
  const streak = streakWeeks(history, profile.goalSessions);
  const left = Math.max(0, profile.goalSessions - w.sessions);
  const bars = [
    { label: 'Sesiones', v: `${w.sessions} de ${profile.goalSessions}`, pct: ringPct(w.sessions, profile.goalSessions), c: C.brasa },
    { label: 'Minutos activos', v: `${w.minutes} de ${profile.goalMinutes}`, pct: ringPct(w.minutes, profile.goalMinutes), c: C.cobalto },
    { label: 'Volumen', v: `${kgShort(w.volume)} de ${kgShort(profile.goalVolume)}`, pct: ringPct(w.volume, profile.goalVolume), c: C.ambar },
  ];
  const start = mondayOf(new Date()).getTime() - 11 * 7 * DAY;
  const today = new Date();

  return (
    <div>
      <div className="flex items-center gap-2.5">
        <span className="grid h-10 w-10 place-items-center rounded-xl bg-[#FF5A2C] text-[#0B0A12]"><Activity size={22} strokeWidth={2.6} /></span>
        <span className="pf-display text-[28px]">Pulso Fit</span>
      </div>

      <p className="mt-10 text-[14px] text-[#A8A5BC]">Esta semana</p>
      <p className="pf-display pf-num mt-1 text-[64px] leading-none">{w.sessions}<span className="text-[#5E5B73]">/{profile.goalSessions}</span></p>
      <p className="mt-2 max-w-[300px] text-[14px] leading-relaxed text-[#C9C6D8]">
        {left === 0 ? `Objetivo cumplido. Llevas ${streak} semanas seguidas en racha.` : `Te ${left === 1 ? 'falta 1 sesión' : `faltan ${left} sesiones`} para cerrar la semana y alargar tu racha de ${streak} semanas.`}
      </p>

      <ul className="mt-7 space-y-4">
        {bars.map(b => (
          <li key={b.label}>
            <div className="flex justify-between text-[13px]"><span className="text-[#C9C6D8]">{b.label}</span><span className="pf-num font-semibold">{b.v}</span></div>
            <div className="mt-1.5 h-2 overflow-hidden rounded-full bg-white/[0.07]"><div className="h-full rounded-full" style={{ width: `${Math.max(3, b.pct * 100)}%`, background: b.c }} /></div>
          </li>
        ))}
      </ul>

      <p className="mt-8 text-[13px] text-[#A8A5BC]">Constancia · últimas 12 semanas</p>
      <div className="mt-2.5 grid grid-flow-col grid-rows-7 gap-[5px]" style={{ gridTemplateColumns: 'repeat(12, 1fr)' }} aria-label="Días entrenados en las últimas 12 semanas" role="img">
        {Array.from({ length: 84 }, (_, i) => {
          const d = new Date(start + i * DAY);
          const n = history.filter(s => sameDay(new Date(s.date), d)).length;
          const future = d > today;
          return <span key={i} title={d.toLocaleDateString('es-ES')} className="aspect-square rounded-[4px]" style={{ background: future ? 'transparent' : n ? C.brasa : 'rgba(239,237,247,.07)', opacity: n ? 0.95 : 1 }} />;
        })}
      </div>
    </div>
  );
}

export function TrendPanel({ data }: { data: FitData }) {
  const { history, profile } = data;
  const weeks = weeklySeries(history, 8);
  const prs = personalRecords(history).slice(0, 4);
  const avg = Math.round(weeks.slice(0, 7).reduce((a, w) => a + w.volume, 0) / 7);
  const prev = weeks[weeks.length - 2]?.volume ?? 0;
  const before = weeks[0]?.volume || 1;
  return (
    <div>
      <p className="text-[14px] text-[#A8A5BC]">Volumen semanal</p>
      <p className="pf-display pf-num mt-1 text-[40px] leading-none">{kgShort(prev)}</p>
      <p className="mt-1 text-[13px] text-[#C9C6D8]">la semana pasada · media de {kgShort(avg)}</p>
      <p className="text-[13px] text-[#FFC85A]">{prev >= before ? '+' : ''}{Math.round(((prev - before) / before) * 100)} % respecto a hace 8 semanas</p>
      <div className="mt-4"><BarChart data={weeks.map(w => ({ label: w.label, value: w.volume }))} goal={profile.goalVolume} color={C.ambar} height={170} format={kgShort} /></div>

      <p className="mt-7 flex items-center gap-2 text-[14px] text-[#A8A5BC]"><Trophy size={15} className="text-[#FFB627]" /> Récords recientes</p>
      <ul className="mt-2 divide-y divide-white/[0.07]">
        {prs.map(p => (
          <li key={p.name} className="flex items-center justify-between gap-3 py-2.5">
            <div className="min-w-0">
              <p className="truncate text-[14px] font-semibold">{p.name}</p>
              <p className="text-[12px] text-[#8C89A3]">{relDate(p.date)}</p>
            </div>
            <span className="pf-display pf-num shrink-0 text-[22px] text-[#FFC85A]">{kg(p.weight)} <span className="pf-app text-[12px] font-medium text-[#A8A5BC]">kg</span></span>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useEffect, useId, useState } from 'react';

const useMounted = () => {
  const [m, setM] = useState(false);
  useEffect(() => { const t = requestAnimationFrame(() => setM(true)); return () => cancelAnimationFrame(t); }, []);
  return m;
};

/** Anillos concéntricos de objetivo (de fuera hacia dentro). */
export function Rings({ rings, size = 150, stroke = 14, gap = 4 }: { rings: { pct: number; color: string; label: string }[]; size?: number; stroke?: number; gap?: number }) {
  const mounted = useMounted();
  const c = size / 2;
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} role="img" aria-label={rings.map(r => `${r.label} ${Math.round(r.pct * 100)} %`).join(', ')}>
      {rings.map((r, i) => {
        const rad = c - stroke / 2 - i * (stroke + gap);
        const len = 2 * Math.PI * rad;
        return (
          <g key={r.label} transform={`rotate(-90 ${c} ${c})`}>
            <circle cx={c} cy={c} r={rad} fill="none" stroke={r.color} strokeOpacity={0.18} strokeWidth={stroke} />
            <circle className="pf-ring" cx={c} cy={c} r={rad} fill="none" stroke={r.color} strokeWidth={stroke} strokeLinecap="round"
              strokeDasharray={len} strokeDashoffset={mounted ? len * (1 - Math.max(0.015, r.pct)) : len} />
          </g>
        );
      })}
    </svg>
  );
}

type Bar = { label: string; value: number };
export function BarChart({ data, goal, color = '#FF5A2C', height = 150, format }: { data: Bar[]; goal?: number; color?: string; height?: number; format: (n: number) => string }) {
  const mounted = useMounted();
  const [hover, setHover] = useState<number | null>(null);
  const W = 320, H = height, top = 14, bottom = 22;
  const max = Math.max(goal ?? 0, ...data.map(d => d.value)) * 1.1 || 1;
  const bw = W / data.length;
  const y = (v: number) => top + (H - top - bottom) * (1 - v / max);
  return (
    <div className="relative">
      <svg viewBox={`0 0 ${W} ${H}`} className="w-full h-auto block" role="img" aria-label="Gráfico de barras por semana" onMouseLeave={() => setHover(null)}>
        {goal ? (
          <g>
            <line x1={0} x2={W} y1={y(goal)} y2={y(goal)} stroke="#EFEDF7" strokeOpacity={0.35} strokeDasharray="3 4" />
            <text x={W} y={y(goal) - 4} textAnchor="end" fontSize={9.5} fill="#A8A5BC">Objetivo</text>
          </g>
        ) : null}
        {data.map((d, i) => {
          const h = mounted ? H - bottom - y(d.value) : 0;
          const last = i === data.length - 1;
          return (
            <g key={i} onMouseEnter={() => setHover(i)}>
              <rect x={i * bw} y={0} width={bw} height={H} fill="transparent" />
              <rect className="pf-bar" x={i * bw + bw * 0.2} y={H - bottom - h} width={bw * 0.6} height={Math.max(0, h)} rx={4}
                fill={color} fillOpacity={hover === i || (hover === null && last) ? 1 : 0.45} />
              <text x={i * bw + bw / 2} y={H - 6} textAnchor="middle" fontSize={9.5} fill={last ? '#EFEDF7' : '#8C89A3'}>{d.label}</text>
            </g>
          );
        })}
      </svg>
      {hover !== null && (
        <div className="pointer-events-none absolute -translate-x-1/2 rounded-lg bg-[#EFEDF7] px-2 py-1 text-[11px] font-semibold text-[#0B0A12] pf-num whitespace-nowrap shadow-lg"
          style={{ left: `${((hover + 0.5) / data.length) * 100}%`, top: `${(y(data[hover].value) / H) * 100 - 22}%` }}>
          {format(data[hover].value)}
        </div>
      )}
    </div>
  );
}

export function LineChart({ data, color = '#FFB627', height = 150, format }: { data: Bar[]; color?: string; height?: number; format: (n: number) => string }) {
  const mounted = useMounted();
  const id = useId().replace(/:/g, '');
  const [hover, setHover] = useState<number | null>(null);
  if (data.length < 2) return <p className="py-8 text-center text-sm text-[#A8A5BC]">Registra al menos dos sesiones de este ejercicio para ver la curva.</p>;
  const W = 320, H = height, top = 12, bottom = 22, left = 30;
  const vals = data.map(d => d.value);
  const lo = Math.floor(Math.min(...vals) * 0.92), hi = Math.ceil(Math.max(...vals) * 1.05) || 1;
  const x = (i: number) => left + ((W - left - 6) * i) / (data.length - 1);
  const y = (v: number) => top + (H - top - bottom) * (1 - (v - lo) / (hi - lo || 1));
  const line = data.map((d, i) => `${i ? 'L' : 'M'}${x(i).toFixed(1)},${y(d.value).toFixed(1)}`).join(' ');
  const area = `${line} L${x(data.length - 1)},${H - bottom} L${x(0)},${H - bottom} Z`;
  const ticks = [lo, Math.round((lo + hi) / 2), hi];
  const shown = hover ?? data.length - 1;
  return (
    <div className="relative">
      <svg viewBox={`0 0 ${W} ${H}`} className="w-full h-auto block" role="img" aria-label="Evolución del peso máximo" onMouseLeave={() => setHover(null)}>
        <defs>
          <linearGradient id={`g${id}`} x1="0" x2="0" y1="0" y2="1">
            <stop offset="0" stopColor={color} stopOpacity={0.35} />
            <stop offset="1" stopColor={color} stopOpacity={0} />
          </linearGradient>
        </defs>
        {ticks.map(t => (
          <g key={t}>
            <line x1={left} x2={W} y1={y(t)} y2={y(t)} stroke="#EFEDF7" strokeOpacity={0.07} />
            <text x={left - 6} y={y(t) + 3} textAnchor="end" fontSize={9.5} fill="#8C89A3">{t}</text>
          </g>
        ))}
        <path d={area} fill={`url(#g${id})`} style={{ opacity: mounted ? 1 : 0, transition: 'opacity .8s' }} />
        <path d={line} fill="none" stroke={color} strokeWidth={2.5} strokeLinejoin="round" strokeLinecap="round"
          pathLength={1} strokeDasharray={1} strokeDashoffset={mounted ? 0 : 1} style={{ transition: 'stroke-dashoffset 1s ease-out' }} />
        <text x={x(0)} y={H - 6} fontSize={9.5} fill="#8C89A3">{data[0].label}</text>
        <text x={x(data.length - 1)} y={H - 6} textAnchor="end" fontSize={9.5} fill="#8C89A3">{data[data.length - 1].label}</text>
        <circle cx={x(shown)} cy={y(data[shown].value)} r={5} fill="#0B0A12" stroke={color} strokeWidth={2.5} />
        {data.map((_, i) => (
          <rect key={i} x={x(i) - (W / data.length) / 2} y={0} width={W / data.length} height={H} fill="transparent" onMouseEnter={() => setHover(i)} />
        ))}
      </svg>
      <div className="pointer-events-none absolute -translate-x-1/2 rounded-lg bg-[#EFEDF7] px-2 py-1 text-[11px] font-semibold text-[#0B0A12] pf-num whitespace-nowrap"
        style={{ left: `${Math.min(88, Math.max(12, (x(shown) / W) * 100))}%`, top: `${(y(data[shown].value) / H) * 100 - 24}%` }}>
        {format(data[shown].value)}{hover !== null ? ` · ${data[shown].label}` : ''}
      </div>
    </div>
  );
}

import { useEffect } from 'react';
import type { ReactNode } from 'react';
import { clsx } from 'clsx';
import { Check, Minus, Plus, X } from 'lucide-react';

export const C = { noche: '#0B0A12', pizarra: '#17161F', brasa: '#FF5A2C', cobalto: '#5B7CFF', ambar: '#FFB627', hielo: '#EFEDF7', gris: '#A8A5BC' };

/** Hoja inferior que se abre dentro del marco del móvil. */
export function Sheet({ title, onClose, children, footer }: { title: string; onClose: () => void; children: ReactNode; footer?: ReactNode }) {
  useEffect(() => {
    const k = (e: KeyboardEvent) => e.key === 'Escape' && onClose();
    window.addEventListener('keydown', k);
    return () => window.removeEventListener('keydown', k);
  }, [onClose]);
  return (
    <div className="absolute inset-0 z-40 flex flex-col justify-end">
      <button aria-label="Cerrar" className="pf-fade absolute inset-0 bg-black/60 cursor-default" onClick={onClose} />
      <div role="dialog" aria-modal="true" aria-label={title} className="pf-sheet relative flex max-h-[88%] flex-col rounded-t-[28px] bg-[#1E1C28] shadow-2xl">
        <div className="flex items-center justify-between px-5 pt-5 pb-3">
          <h2 className="pf-display text-[26px]">{title}</h2>
          <button onClick={onClose} aria-label="Cerrar" className="grid h-9 w-9 place-items-center rounded-full bg-white/10 hover:bg-white/15"><X size={18} /></button>
        </div>
        <div className="pf-scroll flex-1 overflow-y-auto px-5 pb-4">{children}</div>
        {footer && <div className="border-t border-white/10 px-5 pt-3 pb-[46px] lg:pb-5">{footer}</div>}
      </div>
    </div>
  );
}

export function Btn({ children, onClick, kind = 'primary', className, type = 'button', disabled }: { children: ReactNode; onClick?: () => void; kind?: 'primary' | 'ghost' | 'danger' | 'soft'; className?: string; type?: 'button' | 'submit'; disabled?: boolean }) {
  return (
    <button type={type} onClick={onClick} disabled={disabled}
      className={clsx('inline-flex items-center justify-center gap-2 rounded-2xl px-4 h-12 text-[15px] font-semibold transition active:scale-[0.98] disabled:opacity-40',
        kind === 'primary' && 'bg-[#FF5A2C] text-[#0B0A12] hover:bg-[#FF7149]',
        kind === 'soft' && 'bg-white/10 text-[#EFEDF7] hover:bg-white/15',
        kind === 'ghost' && 'text-[#EFEDF7] hover:bg-white/5',
        kind === 'danger' && 'bg-[#3A1A1E] text-[#FF8A8A] hover:bg-[#4A1F25]',
        className)}>
      {children}
    </button>
  );
}

export function Stepper({ label, value, unit, step, onChange }: { label: string; value: number; unit: string; step: number; onChange: (delta: number) => void }) {
  return (
    <div className="min-w-0 flex-1 rounded-2xl bg-white/[0.06] px-2.5 py-2.5">
      <div className="text-center text-[12px] font-medium text-[#A8A5BC]">{label}</div>
      <div className="mt-1 flex items-center justify-between gap-1">
        <button onClick={() => onChange(-step)} aria-label={`Restar ${step} ${unit} a ${label.toLowerCase()}`} className="grid h-8 w-8 shrink-0 place-items-center rounded-full bg-white/10 hover:bg-white/20"><Minus size={15} /></button>
        <div className="min-w-0 text-center leading-none">
          <span className="pf-display pf-num block text-[30px]">{value.toLocaleString('es-ES')}</span>
          <span className="text-[11px] text-[#A8A5BC]">{unit}</span>
        </div>
        <button onClick={() => onChange(step)} aria-label={`Sumar ${step} ${unit} a ${label.toLowerCase()}`} className="grid h-8 w-8 shrink-0 place-items-center rounded-full bg-white/10 hover:bg-white/20"><Plus size={15} /></button>
      </div>
    </div>
  );
}

export type ToastMsg = { id: number; text: string; action?: { label: string; run: () => void } };
export function Toast({ toast, onClose }: { toast: ToastMsg | null; onClose: () => void }) {
  useEffect(() => {
    if (!toast) return;
    const t = window.setTimeout(onClose, 4200);
    return () => window.clearTimeout(t);
  }, [toast, onClose]);
  if (!toast) return null;
  return (
    <div role="status" className="pf-pop absolute left-4 right-4 top-4 z-50 flex items-center gap-3 rounded-2xl bg-[#EFEDF7] px-4 py-3 text-[14px] font-medium text-[#0B0A12] shadow-xl lg:top-11">
      <span className="grid h-6 w-6 shrink-0 place-items-center rounded-full bg-[#FF5A2C]"><Check size={14} strokeWidth={3} /></span>
      <span className="flex-1">{toast.text}</span>
      {toast.action && <button className="font-bold text-[#C23A12] underline-offset-2 hover:underline" onClick={() => { toast.action!.run(); onClose(); }}>{toast.action.label}</button>}
    </div>
  );
}

export function Field({ label, error, children, hint }: { label: string; error?: string; hint?: string; children: ReactNode }) {
  return (
    <label className="block">
      <span className="mb-1.5 block text-[13px] font-medium text-[#A8A5BC]">{label}</span>
      {children}
      {error ? <span className="mt-1 block text-[12px] text-[#FF8A8A]">{error}</span> : hint ? <span className="mt-1 block text-[12px] text-[#8C89A3]">{hint}</span> : null}
    </label>
  );
}
