const DAY = 86_400_000;
const mondayOf = (d: Date) => {
  const x = new Date(d.getFullYear(), d.getMonth(), d.getDate());
  x.setDate(x.getDate() - ((x.getDay() + 6) % 7));
  return x;
};

/** Historial de 10 semanas con progresión de cargas (determinista). */
export function buildHistory(now = new Date()): Session[] {
  const out: Session[] = [];
  const monday = mondayOf(now);
  const todayIdx = (now.getDay() + 6) % 7;
  const plan = ['empuje', 'pierna', 'tiron', 'full'];
  const hours = [7, 19, 18, 10];
  for (let w = 10; w >= 0; w--) {
    const base = monday.getTime() - w * 7 * DAY;
    let days = w % 4 === 2 ? [0, 2, 4] : [0, 1, 3, 5];
    if (w === 0) days = [0, 1].filter(d => d < todayIdx);
    days.forEach((d, i) => {
      const r = ROUTINES.find(x => x.id === plan[i % plan.length])!;
      const prog = (10 - w) / 10; // 0 → 1 a lo largo de las semanas
      const date = new Date(base + d * DAY);
      date.setHours(hours[i % hours.length], (w * 7 + i * 13) % 60);
      out.push({
        id: `h${w}-${d}`,
        routineId: r.id,
        name: r.name,
        date: date.toISOString(),
        minutes: r.minutes + ((w + i) % 5) * 3 - 6,
        exercises: r.exercises.map(e => ({
          name: e.name,
          sets: e.sets,
          reps: e.reps,
          weight: e.weight === 0 ? 0 : Math.round((e.weight * (0.84 + 0.16 * prog)) / 2.5) * 2.5,
        })),
      });
    });
  }
  return out.sort((a, b) => b.date.localeCompare(a.date));
}

