import { useEffect, useState } from 'react';
import type { Routine, Session } from '../data/seed';
import { uid } from './store';

export type LiveSet = { reps: number; weight: number; done: boolean };
export type LiveExercise = { name: string; unit: 'reps' | 's'; rest: number; sets: LiveSet[] };
export type Rest = { total: number; endsAt: number; left: number };
export type Live = {
  routineId: string;
  name: string;
  exercises: LiveExercise[];
  cur: { ex: number; set: number };
  startedAt: number; // inicio del tramo actual sin pausa
  accMs: number; // tiempo acumulado antes del tramo actual
  paused: boolean;
  rest: Rest | null;
  finished: boolean;
};

export const elapsedMs = (l: Live, now: number) => l.accMs + (l.paused ? 0 : now - l.startedAt);
export const restLeftMs = (r: Rest, paused: boolean, now: number) => (paused ? r.left : Math.max(0, r.endsAt - now));
export const totalSets = (l: Live) => l.exercises.reduce((a, e) => a + e.sets.length, 0);
export const doneSets = (l: Live) => l.exercises.reduce((a, e) => a + e.sets.filter(s => s.done).length, 0);
export const liveVolume = (l: Live) =>
  l.exercises.reduce((a, e) => a + e.sets.filter(s => s.done).reduce((b, s) => b + s.reps * s.weight, 0), 0);

function nextOpen(l: Live): { ex: number; set: number } | null {
  const { ex, set } = l.cur;
  const sameEx = l.exercises[ex].sets.findIndex((s, i) => i > set && !s.done);
  if (sameEx >= 0) return { ex, set: sameEx };
  for (let k = 1; k <= l.exercises.length; k++) {
    const e = (ex + k) % l.exercises.length;
    const si = l.exercises[e].sets.findIndex(s => !s.done);
    if (si >= 0) return { ex: e, set: si };
  }
  return null;
}

export function startLive(r: Routine): Live {
  return {
    routineId: r.id,
    name: r.name,
    exercises: r.exercises.map(e => ({ name: e.name, unit: e.unit ?? 'reps', rest: e.rest, sets: Array.from({ length: e.sets }, () => ({ reps: e.reps, weight: e.weight, done: false })) })),
    cur: { ex: 0, set: 0 },
    startedAt: Date.now(),
    accMs: 0,
    paused: false,
    rest: null,
    finished: false,
  };
}

/** Sesión en curso: temporizador total, descansos y registro serie a serie. */
export function useLiveSession() {
  const [live, setLive] = useState<Live | null>(null);
  const [now, setNow] = useState(Date.now());

  useEffect(() => {
    if (!live) return;
    const t = window.setInterval(() => setNow(Date.now()), 250);
    return () => window.clearInterval(t);
  }, [live !== null]);

  // Fin automático del descanso
  useEffect(() => {
    if (live?.rest && !live.paused && now >= live.rest.endsAt) setLive(l => (l ? { ...l, rest: null } : l));
  }, [now, live]);

  const patch = (fn: (l: Live) => Live) => setLive(l => (l ? fn(l) : l));

  return {
    live,
    now,
    start: (r: Routine) => { setNow(Date.now()); setLive(startLive(r)); },
    discard: () => setLive(null),
    togglePause: () =>
      patch(l => {
        const t = Date.now();
        if (l.paused) {
          return { ...l, paused: false, startedAt: t, rest: l.rest ? { ...l.rest, endsAt: t + l.rest.left } : null };
        }
        return { ...l, paused: true, accMs: l.accMs + (t - l.startedAt), rest: l.rest ? { ...l.rest, left: Math.max(0, l.rest.endsAt - t) } : null };
      }),
    adjust: (field: 'reps' | 'weight', delta: number) =>
      patch(l => {
        const exercises = l.exercises.map((e, ei) =>
          ei !== l.cur.ex ? e : { ...e, sets: e.sets.map((s, si) => (si !== l.cur.set ? s : { ...s, [field]: Math.max(0, Math.round((s[field] + delta) * 10) / 10) })) });
        return { ...l, exercises };
      }),
    completeSet: () =>
      patch(l => {
        const { ex, set } = l.cur;
        const doneSet = l.exercises[ex].sets[set];
        const exercises = l.exercises.map((e, ei) =>
          ei !== ex ? e : { ...e, sets: e.sets.map((s, si) => (si === set ? { ...s, done: true } : si > set && !s.done ? { ...s, weight: doneSet.weight, reps: doneSet.reps } : s)) });
        const upd = { ...l, exercises };
        const nxt = nextOpen(upd);
        if (!nxt) return { ...upd, finished: true, rest: null };
        const restS = l.exercises[ex].rest;
        const t = Date.now();
        return { ...upd, cur: nxt, rest: restS > 0 ? { total: restS * 1000, endsAt: t + restS * 1000, left: restS * 1000 } : null };
      }),
    undoSet: (ex: number, set: number) =>
      patch(l => ({ ...l, finished: false, cur: { ex, set }, rest: null, exercises: l.exercises.map((e, ei) => (ei !== ex ? e : { ...e, sets: e.sets.map((s, si) => (si === set ? { ...s, done: false } : s)) })) })),
    select: (ex: number, set: number) => patch(l => ({ ...l, cur: { ex, set }, rest: null })),
    skipRest: () => patch(l => ({ ...l, rest: null })),
    addRest: (sec: number) =>
      patch(l => (l.rest ? { ...l, rest: { total: l.rest.total + sec * 1000, endsAt: l.rest.endsAt + sec * 1000, left: l.rest.left + sec * 1000 } } : l)),
    requestFinish: () => patch(l => ({ ...l, finished: true, rest: null })),
    keepGoing: () => patch(l => ({ ...l, finished: false })),
  };
}
export type LiveApi = ReturnType<typeof useLiveSession>;

export function toSession(l: Live, now: number): Session {
  return {
    id: uid(),
    routineId: l.routineId,
    name: l.name,
    date: new Date().toISOString(),
    minutes: Math.max(1, Math.round(elapsedMs(l, now) / 60000)),
    exercises: l.exercises
      .map(e => {
        const done = e.sets.filter(s => s.done);
        if (!done.length) return null;
        const reps = Math.round(done.reduce((a, s) => a + s.reps, 0) / done.length);
        const weight = Math.max(...done.map(s => s.weight));
        return { name: e.name, sets: done.length, reps, weight };
      })
      .filter((x): x is NonNullable<typeof x> => x !== null),
  };
}

import type { Profile, Routine, Session } from '../data/seed';

const DAY = 86_400_000;
export const kg = (n: number) => n.toLocaleString('es-ES', { maximumFractionDigits: 1 });
export const kgShort = (n: number) => (n >= 1000 ? `${(n / 1000).toLocaleString('es-ES', { maximumFractionDigits: 1 })} t` : `${kg(n)} kg`);
export const clock = (ms: number) => {
  const s = Math.max(0, Math.floor(ms / 1000));
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const ss = String(s % 60).padStart(2, '0');
  return h ? `${h}:${String(m).padStart(2, '0')}:${ss}` : `${m}:${ss}`;
};

export const mondayOf = (d: Date) => {
  const x = new Date(d.getFullYear(), d.getMonth(), d.getDate());
  x.setDate(x.getDate() - ((x.getDay() + 6) % 7));
  return x;
};
export const dayIdx = (d: Date) => (d.getDay() + 6) % 7;
export const sameDay = (a: Date, b: Date) => a.toDateString() === b.toDateString();

export function relDate(iso: string, now = new Date()) {
  const d = new Date(iso);
  const diff = Math.round((new Date(now.toDateString()).getTime() - new Date(d.toDateString()).getTime()) / DAY);
  if (diff === 0) return 'Hoy';
  if (diff === 1) return 'Ayer';
  if (diff < 7) return `Hace ${diff} días`;
  return d.toLocaleDateString('es-ES', { weekday: 'short', day: 'numeric', month: 'short' });
}

export const sessionVolume = (s: Session) => s.exercises.reduce((a, e) => a + e.sets * e.reps * e.weight, 0);
export const sessionSets = (s: Session) => s.exercises.reduce((a, e) => a + e.sets, 0);

/** Sesiones de la semana con desplazamiento (0 = esta semana, 1 = la anterior…). */
export function weekSessions(history: Session[], offset = 0, now = new Date()) {
  const start = mondayOf(now).getTime() - offset * 7 * DAY;
  const end = start + 7 * DAY;
  return history.filter(s => { const t = new Date(s.date).getTime(); return t >= start && t < end; });
}

export function weekSummary(history: Session[], offset = 0) {
  const list = weekSessions(history, offset);
  return {
    sessions: list.length,
    minutes: list.reduce((a, s) => a + s.minutes, 0),
    volume: list.reduce((a, s) => a + sessionVolume(s), 0),
    list,
  };
}

/** Semanas seguidas cumpliendo el objetivo de sesiones (la actual cuenta si ya se cumplió). */
export function streakWeeks(history: Session[], goal: number) {
  let n = weekSessions(history, 0).length >= goal ? 1 : 0;
  for (let w = 1; w < 60; w++) {
    if (weekSessions(history, w).length >= Math.min(goal, 3)) n++;
    else break;
  }
  return n;
}

export function weeklySeries(history: Session[], weeks = 8) {
  return Array.from({ length: weeks }, (_, i) => {
    const off = weeks - 1 - i;
    const s = weekSummary(history, off);
    const start = new Date(mondayOf(new Date()).getTime() - off * 7 * DAY);
    return { label: off === 0 ? 'Esta' : start.toLocaleDateString('es-ES', { day: 'numeric', month: 'short' }).replace('.', ''), ...s };
  });
}

/** Mejor peso por sesión para un ejercicio, de más antigua a más reciente. */
export function exerciseSeries(history: Session[], name: string) {
  return history
    .filter(s => s.exercises.some(e => e.name === name))
    .map(s => ({ date: s.date, weight: Math.max(...s.exercises.filter(e => e.name === name).map(e => e.weight)) }))
    .reverse();
}

export function personalRecords(history: Session[]) {
  const map = new Map<string, { name: string; weight: number; date: string }>();
  for (const s of [...history].reverse()) {
    for (const e of s.exercises) {
      const cur = map.get(e.name);
      if (e.weight > 0 && (!cur || e.weight > cur.weight)) map.set(e.name, { name: e.name, weight: e.weight, date: s.date });
    }
  }
  return [...map.values()].sort((a, b) => b.date.localeCompare(a.date) || b.weight - a.weight);
}

export function nextRoutine(routines: Routine[], history: Session[]) {
  if (!routines.length) return null;
  const order = ['empuje', 'pierna', 'tiron', 'full'];
  const last = history[0];
  if (!last) return routines[0];
  const i = order.indexOf(last.routineId);
  const want = order[(i + 1) % order.length];
  return routines.find(r => r.id === want) ?? routines.find(r => r.id !== last.routineId) ?? routines[0];
}

export const ringPct = (value: number, goal: number) => (goal > 0 ? Math.min(1, value / goal) : 0);
export const goalsOf = (p: Profile) => ({ sessions: p.goalSessions, minutes: p.goalMinutes, volume: p.goalVolume });

import { useEffect, useState } from 'react';
import { DEFAULT_PROFILE, ROUTINES, buildHistory } from '../data/seed';
import type { Profile, Routine, Session } from '../data/seed';

const KEY = 'pulso-fit:v1';

export type FitData = { profile: Profile; routines: Routine[]; history: Session[] };

const fresh = (): FitData => ({ profile: { ...DEFAULT_PROFILE }, routines: ROUTINES.map(r => ({ ...r, exercises: r.exercises.map(e => ({ ...e })) })), history: buildHistory() });

function load(): FitData {
  try {
    const raw = localStorage.getItem(KEY);
    if (raw) {
      const d = JSON.parse(raw) as FitData;
      if (d && d.profile && Array.isArray(d.routines) && Array.isArray(d.history)) return d;
    }
  } catch { /* almacenamiento no disponible */ }
  return fresh();
}

export const uid = () => Math.random().toString(36).slice(2, 9);

export function useFitness() {
  const [data, setData] = useState<FitData>(load);

  useEffect(() => {
    try { localStorage.setItem(KEY, JSON.stringify(data)); } catch { /* sin almacenamiento */ }
  }, [data]);

  return {
    data,
    saveRoutine: (r: Routine) =>
      setData(d => ({ ...d, routines: d.routines.some(x => x.id === r.id) ? d.routines.map(x => (x.id === r.id ? r : x)) : [...d.routines, r] })),
    deleteRoutine: (id: string) => setData(d => ({ ...d, routines: d.routines.filter(r => r.id !== id) })),
    addSession: (s: Session) => setData(d => ({ ...d, history: [s, ...d.history].sort((a, b) => b.date.localeCompare(a.date)) })),
    deleteSession: (id: string) => setData(d => ({ ...d, history: d.history.filter(s => s.id !== id) })),
    restoreSession: (s: Session) => setData(d => ({ ...d, history: [...d.history, s].sort((a, b) => b.date.localeCompare(a.date)) })),
    updateProfile: (p: Profile) => setData(d => ({ ...d, profile: p })),
    reset: () => setData(fresh()),
  };
}
export type Fit = ReturnType<typeof useFitness>;
